// Server Component - No useEffect or client bundle overhead
import { Suspense } from 'react';
import MetricsSkeleton from '@/components/MetricsSkeleton';

async function LiveMetrics() {
  // Cached fetch with incremental revalidation
  const res = await fetch('https://api.example.com/analytics', {
    next: { revalidate: 60 } // Revalidate every 60s
  });
  const data = await res.json();

  return (
    <div className="grid grid-cols-3 gap-4">
      {data.metrics.map(item => (
        <div key={item.id} className="p-4 rounded-xl bg-neutral-900 border border-neutral-800">
          <h3 className="text-sm text-neutral-400">{item.label}</h3>
          <p className="text-2xl font-bold text-white">{item.value}</p>
        </div>
      ))}
    </div>
  );
}

export default function DashboardPage() {
  return (
    <main className="p-8 max-w-5xl mx-auto">
      <h1 className="text-3xl font-bold mb-6">Analytics Overview</h1>
      <Suspense fallback={<MetricsSkeleton />}>
        <LiveMetrics />
      </Suspense>
    </main>
  );
}

// Use startTransition to yield control back to the main thread
import { useTransition } from 'react';

function SearchInterface() {
  const [isPending, startTransition] = useTransition();
  const [results, setResults] = useState([]);

  const handleSearch = (e) => {
    const query = e.target.value;
    // Urgent: input update shows immediately
    setInputValue(query);

    // Non-urgent: deferred update does not block user typing or UI painting
    startTransition(() => {
      const filtered = performHeavyComputation(query);
      setResults(filtered);
    });
  };

  return <input onChange={handleSearch} />;
}

import { create } from 'zustand';
import { persist } from 'zustand/middleware';

export const useCartStore = create(
  persist(
    (set, get) => ({
      items: [],
      addItem: (product) =>
        set((state) => ({
          items: [...state.items, product],
        })),
      removeItem: (id) =>
        set((state) => ({
          items: state.items.filter((i) => i.id !== id),
        })),
      clearCart: () => set({ items: [] }),
      getTotal: () =>
        get().items.reduce((sum, item) => sum + item.price, 0),
    }),
    { name: 'shopping-cart-storage' }
  )
);

import { streamText } from 'ai';
import { openai } from '@ai-sdk/openai';

export const runtime = 'edge';

export async function POST(req) {
  const { messages } = await req.json();

  const result = streamText({
    model: openai('gpt-4o'),
    system: 'You are an expert full-stack developer assistant.',
    messages,
  });

  return result.toDataStreamResponse();
}

'use client';
import { useChat } from 'ai/react';

export default function ChatInterface() {
  const { messages, input, handleInputChange, handleSubmit, isLoading } = useChat();

  return (
    <div className="max-w-2xl mx-auto p-4 flex flex-col h-[500px]">
      <div className="flex-1 overflow-y-auto space-y-4 mb-4">
        {messages.map((m) => (
          <div key={m.id} className={m.role === 'user' ? 'text-right' : 'text-left'}>
            <span className={`inline-block p-3 rounded-2xl ${m.role === 'user' ? 'bg-blue-600 text-white' : 'bg-neutral-800 text-neutral-200'}`}>
              {m.content}
            </span>
          </div>
        ))}
      </div>
      <form onSubmit={handleSubmit} className="flex gap-2">
        <input value={input} onChange={handleInputChange} placeholder="Ask anything..." className="flex-1 p-3 rounded-xl bg-neutral-900 border border-neutral-800 text-white" />
        <button type="submit" disabled={isLoading} className="px-5 py-3 bg-blue-600 rounded-xl text-white font-bold">Send</button>
      </form>
    </div>
  );
}

export async function POST(req) {
  const { prompt } = await req.json();

  const response = await fetch('http://localhost:11434/api/generate', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      model: 'deepseek-r1:8b',
      prompt,
      stream: false
    })
  });

  const data = await response.json();
  return Response.json({ response: data.response });
}
